WITH filtered AS (SELECT *, QUARTER(opened_date) opened_date_quarter FROM stores WHERE region IS NOT NULL AND region = 'Central'), with_latest AS (SELECT s.*, latest.order_order_date, latest.order_status FROM filtered s LEFT JOIN LATERAL (SELECT c.order_date AS order_order_date, c.status AS order_status FROM orders c WHERE c.store_id = s.id AND c.order_date <= s.opened_date ORDER BY c.order_date DESC, c.id DESC LIMIT 1) latest ON TRUE), with_latest_stores AS (SELECT s.*, x.shipping_fee, x.discount FROM with_latest s LEFT JOIN LATERAL (SELECT c.shipping_fee, c.discount FROM orders c WHERE c.store_id = s.id AND c.order_date <= s.order_order_date ORDER BY c.order_date DESC, c.id DESC LIMIT 1) x ON TRUE), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_status ORDER BY opened_date DESC NULLS FIRST, id) AS dedup_rank FROM with_latest_stores) t WHERE dedup_rank = 1), eligible AS (SELECT s.* FROM deduped s WHERE EXISTS (SELECT 1 FROM store_sales ch WHERE ch.store_id = s.id AND ch.sale_date >= s.order_order_date)), by_type AS (SELECT * FROM (SELECT city, order_status, discount FROM eligible) src PIVOT (AVG(discount) AS amount, COUNT(1) AS n FOR order_status IN ('CANCELLED' AS cancelled, 'RETURNED' AS returned))) SELECT city, cancelled_n, returned_amount FROM by_type ORDER BY returned_amount DESC
